#include <atomic>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <string>
#include <vector>
#include <thread>
#include <map>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <immintrin.h>
struct Stat { long long sum=0; unsigned long long count=0; int lo=999,hi=-999; void add(int t){sum+=t; count++; lo=std::min(lo,t);hi=std::max(hi,t);} void merge(const Stat&s){sum+=s.sum;count+=s.count;lo=std::min(lo,s.lo);hi=std::max(hi,s.hi);} };
struct Entry { uint64_t key=0; std::string name; Stat st; };
static uint64_t load(const char*p){uint64_t x;memcpy(&x,p,8);return x;}
static uint64_t zero(uint64_t x){return (x-0x0101010101010101ULL)&~x&0x8080808080808080ULL;}
static void worker(const char*begin,const char*end,std::vector<Entry>&tab){
 const char*p=begin;
 while(p<end){const char*name=p;uint64_t w=load(p),first=w,h=0; unsigned len=0;uint64_t mask;
 while(!(mask=zero(w^0x3b3b3b3b3b3b3b3bULL))){h=_mm_crc32_u64(h,w);p+=8;len+=8;w=load(p);}
 unsigned tail=__builtin_ctzll(mask)/8;w &= (1ULL<<(tail*8))-1;h=_mm_crc32_u64(h,w);p+=tail+1;len+=tail;
 int sign=1;if(*p=='-'){sign=-1;p++;}int t=*p++-'0';if(*p!='.')t=t*10+*p++-'0';p++;t=(t*10+*p++-'0')*sign;p++;
 unsigned idx=h&2047;while(tab[idx].st.count && (tab[idx].name.size()!=len||memcmp(tab[idx].name.data(),name,len)))idx=(idx+1)&2047;
 Entry&e=tab[idx];if(!e.st.count)e.name.assign(name,len);e.st.add(t);
 }
}
static std::string fmt(long long x){return (x<0?"-":"")+std::to_string(llabs(x)/10)+"."+std::to_string(llabs(x)%10);}
int main(int argc,char**argv){if(argc!=2)return 1;int fd=open(argv[1],O_RDONLY);struct stat sb;if(fd<0||fstat(fd,&sb))return 1;size_t n=sb.st_size;if(!n){printf("{}");return 0;}char*data=(char*)mmap(nullptr,n+4096,PROT_READ,MAP_PRIVATE,fd,0);if(data==MAP_FAILED)return 1;
 // Map an anonymous trailing page so wide loads at EOF are always valid.
 size_t page=(n+4095)&~size_t(4095);void*tail=mmap(data+page,4096,PROT_READ,MAP_PRIVATE|MAP_ANONYMOUS|MAP_FIXED,-1,0);(void)tail;
 constexpr int T=4;std::vector<Entry> tabs[T];std::thread th[T];const char*cuts[T+1];cuts[0]=data;cuts[T]=data+n;
 for(int i=1;i<T;i++){const char*p=data+n*i/T;while(p<data+n&&p[-1]!='\n')p++;cuts[i]=p;}
 for(int i=0;i<T;i++){tabs[i].resize(2048);th[i]=std::thread(worker,cuts[i],cuts[i+1],std::ref(tabs[i]));}
 for(auto&t:th)t.join();std::map<std::string,Stat> result;for(auto&tab:tabs)for(auto&e:tab)if(e.st.count)result[e.name].merge(e.st);
 std::string out="{";bool first=true;for(auto&[name,s]:result){if(!first)out+=", ";first=false;unsigned long long a=llabs(s.sum);long long mean=(a+s.count/2)/s.count;if(s.sum<0)mean=-mean;out+=name+"="+fmt(s.lo)+"/"+fmt(mean)+"/"+fmt(s.hi);}out+="}";fwrite(out.data(),1,out.size(),stdout);return 0;
}

