from pathlib import Path
s=Path('/work/iomodes.cpp').read_text()
s=s.replace('#include <algorithm>','#include <algorithm>\n#include <linux/aio_abi.h>\n#include <sys/syscall.h>\n#include <cerrno>')
s=s.replace('#ifndef WARM','#ifndef DEPTH\n#define DEPTH 2\n#endif\n#ifndef WARM')
a=s.index(' auto job=[&](int t){');b=s.index(' for(int i=1;i<T;i++)th[i]=',a)
s=s[:a]+''' auto job=[&](int t){
 int readfd=-1;bool direct=true; aio_context_t ctx=0;bool aio=false;
 struct Slot{char*buf=nullptr;size_t off=0,nr=0;bool valid=false,warm=false,done=false;struct iocb cb{};} slots[DEPTH];
 size_t allocsz=(CHUNK+8192+2097151)&~size_t(2097151);
 auto sync_read=[&](Slot&s){size_t size=std::min(n-s.off,size_t(CHUNK+64));size_t nr=0;
 while(nr<size){size_t req=direct?((size-nr+4095)&~size_t(4095)):size-nr;ssize_t r=pread(readfd,s.buf+nr,req,s.off+nr);
 if(r<0&&errno==EINTR)continue;
 if(r<0 && direct){close(readfd);readfd=open(argv[1],O_RDONLY);direct=false;continue;}
 if(r<=0)abort();nr+=r;
 }s.nr=nr;s.done=true;};
 auto prepare=[&](Slot&s){size_t j=next.fetch_add(1);s.valid=j<jobs.size();if(!s.valid)return;s.off=jobs[j].off;s.warm=jobs[j].warm;s.done=s.warm;
 if(s.warm)return;
 if(readfd<0){readfd=open(argv[1],O_RDONLY|O_DIRECT);if(readfd<0){readfd=open(argv[1],O_RDONLY);direct=false;}advice(readfd);if(direct && syscall(SYS_io_setup,DEPTH,&ctx)==0)aio=true;}
 if(!s.buf){s.buf=(char*)aligned_alloc(2097152,allocsz);if(!s.buf)abort();madvise(s.buf,allocsz,MADV_HUGEPAGE);memset(s.buf,0,allocsz);madvise(s.buf,allocsz,25);}
 if(aio && direct){s.cb={};s.cb.aio_data=&s-slots;s.cb.aio_lio_opcode=IOCB_CMD_PREAD;s.cb.aio_fildes=readfd;s.cb.aio_buf=(uint64_t)s.buf;s.cb.aio_nbytes=(std::min(n-s.off,size_t(CHUNK+64))+4095)&~size_t(4095);s.cb.aio_offset=s.off;struct iocb*cb=&s.cb;if(syscall(SYS_io_submit,ctx,1,&cb)==1)return;}
 sync_read(s);
 };
 for(auto&s:slots)prepare(s);
 unsigned current=0;
 while(slots[current].valid){auto&s=slots[current];
 while(!s.done){struct io_event ev[DEPTH];int r=syscall(SYS_io_getevents,ctx,1,DEPTH,ev,nullptr);if(r<0&&errno==EINTR)continue;if(r<=0)abort();for(int i=0;i<r;i++){auto&slot=slots[ev[i].data];if(ev[i].res<(long)std::min(n-slot.off,size_t(CHUNK+64))){sync_read(slot);}else{slot.nr=ev[i].res;slot.done=true;}}}
 const char*b,*e;
 if(s.warm){b=data+s.off;e=data+std::min(n,s.off+CHUNK);if(s.off){while(b<data+n&&*b!='\\n')b++;b++;}if(s.off+CHUNK<n){while(e<data+n&&*e!='\\n')e++;e++;}}
 else{memset(s.buf+s.nr,0,64);b=s.buf;e=s.buf+std::min(size_t(CHUNK),s.nr);if(s.off){while(b<s.buf+s.nr&&*b!='\\n')b++;b++;}if(s.off+CHUNK<n){while(e<s.buf+s.nr&&*e!='\\n')e++;e++;}}
 worker(b,e,tabs[t]);prepare(s);current=(current+1)%DEPTH;
 }
 if(aio)syscall(SYS_io_destroy,ctx);if(readfd>=0)close(readfd);for(auto&s:slots)free(s.buf);
 };
