import subprocess,time,json
from pathlib import Path
script='/work/submission/run.sh'
expected=Path('/work/base.out').read_bytes()
results={}
for path,reps in [('/data/measurements-dev.txt',3),('/work/measurements-1b.txt',5),('/work/stress-single.txt',3),('/work/stress-mixed.txt',3)]:
 times=[]
 for i in range(reps):
  start=time.perf_counter();actual=subprocess.check_output([script,path]);times.append(time.perf_counter()-start)
  if 'measurements' in path:assert actual==expected
  elif 'single' in path:assert actual==b'{Jos=99.9/99.9/99.9}'
  else:assert actual=='{Abha=0.0/0.1/0.1, Jos=99.9/99.9/99.9, Wau=-99.9/-99.9/-99.9, Ürümqi=-0.1/-0.1/0.0}'.encode()
 results[path]={'times':times,'best':min(times),'median':sorted(times)[len(times)//2]}
 print(path,results[path],flush=True)
Path('/work/final-benchmark.json').write_text(json.dumps(results,indent=2))

